Lemma conv_kind : forall k a cnt, lept_arg_ok k a -> 0 <= cnt -> cnt + 96 <= INT_MAX ->
  exists ps1 n, conv_pieces cnt (kind_dir k) a = Some (ps1, cnt + n) /\ n = zlength (concat ps1)
